const item = $input.first();
const json = item.json;

let body = json.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = null; }
}
if (!body || typeof body !== 'object') {
  body = json;
}

const dimensions = body.dimensions;

if (!dimensions || !Array.isArray(dimensions) || dimensions.length === 0) {
  return [{
    json: {
      _error: true,
      statusCode: 400,
      body: { error: 'Missing required field: dimensions' }
    }
  }];
}

return [{
  json: {
    _error: false,
    dimensions: dimensions,
    overallLevel: body.overallLevel || 'No evaluado',
    totalScore: body.totalScore || 0,
    maxScore: body.maxScore || 96
  }
}];

const data = $input.first().json;
if (data._error) {
  return [{ json: { statusCode: data.statusCode, body: data.body } }];
}
return [$input.first()];

const data = $input.first().json;
const dimensions = data.dimensions;
const overallLevel = data.overallLevel;
const totalScore = data.totalScore;
const maxScore = data.maxScore;

const weakAreas = dimensions
  .filter(d => d.level === 'Muy Baja' || d.level === 'Baja')
  .map(d => `${d.name}: ${d.score}/${d.maxScore} (${d.level})`)
  .join('\n');

const strongAreas = dimensions
  .filter(d => d.level === 'Alta')
  .map(d => `${d.name}: ${d.score}/${d.maxScore} (${d.level})`)
  .join('\n');

const mediumAreas = dimensions
  .filter(d => d.level === 'Media')
  .map(d => `${d.name}: ${d.score}/${d.maxScore} (${d.level})`)
  .join('\n');

const courses = [
  { name: 'Comunicacion Asertiva', description: 'Domina el arte de expresar tus ideas con claridad, respeto y confianza.' },
  { name: 'Construccion Colectiva', description: 'Colabora de manera efectiva para alcanzar objetivos comunes.' },
  { name: 'Desarrollo de Si mismo', description: 'Explora el autoconocimiento, la autoestima y el crecimiento personal.' },
  { name: 'Flexibilidad y Adaptabilidad', description: 'Desbloquea tu potencial creativo para resolver problemas de forma innovadora.' },
  { name: 'Gestion del Tiempo', description: 'Optimiza tu productividad y reduce el estrés laboral.' },
  { name: 'Gestion Emocional', description: 'Gestiona tus emociones para un mejor bienestar personal y profesional.' },
  { name: 'Liderazgo', description: 'Desarrolla habilidades de liderazgo basadas en la empatía y la comunicación efectiva.' },
  { name: 'Resistencia a la Frustracion', description: 'Fortalece tu capacidad para superar la adversidad y crecer a partir de las dificultades.' },
  { name: 'Resolucion de Conflictos', description: 'Mejora tu capacidad de análisis, evaluación y toma de decisiones.' }
];

const coursesList = courses.map(c => `- ${c.name}: ${c.description}`).join('\n');

const prompt = `Basado en el siguiente diagnóstico de un usuario, recomienda un roadmap personalizado de cursos.

## Resultado del Diagnóstico
- Nivel general: ${overallLevel}
- Puntuación: ${totalScore}/${maxScore}

## Áreas Débiles (que necesitan mejorar)
${weakAreas || 'No hay áreas débiles identificadas'}

## Áreas Medias (con potencial de mejora)
${mediumAreas || 'No hay áreas medias'}

## Áreas Fuertes (fortalezas)
${strongAreas || 'No hay áreas fuertes identificadas'}

## Cursos Disponibles
${coursesList}

## Instrucciones
1. Analiza las áreas débiles y medias del usuario
2. Recomienda entre 3 y 5 cursos en orden de prioridad
3. Para cada curso, explica brevemente por qué es relevante para el usuario
4. Sugiere un orden de estudio lógico
5. Incluye una estimación de tiempo sugerida para cada curso

Responde EXACTAMENTE en este formato JSON (sin texto adicional):
{
  "roadmap": [
    {
      "course": "Nombre del Curso",
      "priority": 1,
      "reason": "Breve explicación",
      "estimatedWeeks": 2
    }
  ],
  "summary": "Resumen general del roadmap"
}`;

return [{
  json: {
    chatInput: prompt,
    overallLevel,
    totalScore,
    maxScore
  }
}];

const agentOutput = $input.first().json;
const previousData = $('Prepare Prompt').first().json;

try {
  let content = agentOutput.output || agentOutput.text || '';

  // If the output is an object, use it directly
  if (typeof agentOutput === 'object' && agentOutput.output) {
    try {
      const parsed = JSON.parse(agentOutput.output);
      return [{
        json: {
          success: true,
          roadmap: parsed.roadmap || [],
          summary: parsed.summary || '',
          diagnostic: {
            overallLevel: previousData.overallLevel,
            totalScore: previousData.totalScore,
            maxScore: previousData.maxScore
          }
        }
      }];
    } catch (e) {
      // Not JSON, continue with string parsing
    }
  }

  // Try to parse as JSON
  let roadmap;
  try {
    roadmap = JSON.parse(content);
  } catch (e) {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      roadmap = JSON.parse(jsonMatch[0]);
    } else {
      throw new Error('Could not parse AI Agent response as JSON');
    }
  }

  return [{
    json: {
      success: true,
      roadmap: roadmap.roadmap || [],
      summary: roadmap.summary || '',
      diagnostic: {
        overallLevel: previousData.overallLevel,
        totalScore: previousData.totalScore,
        maxScore: previousData.maxScore
      }
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      error: error.message,
      rawResponse: agentOutput
    }
  }];
}

const data = $input.first().json;

if (data.success) {
  return [{
    json: {
      statusCode: 200,
      body: {
        success: true,
        roadmap: data.roadmap,
        summary: data.summary,
        diagnostic: data.diagnostic
      }
    }
  }];
} else {
  return [{
    json: {
      statusCode: 500,
      body: {
        success: false,
        error: data.error || 'Failed to generate roadmap'
      }
    }
  }];
}
